Proceso MenuOperaciones
    Definir opcion Como Entero;
    Definir a Como Entero;
    Definir b Como Entero;
    Leer opcion, a, b;
    Segun opcion Hacer
        1:
            Escribir a + b;
        2:
            Escribir a - b;
        3:
            Escribir a * b;
        4:
            Escribir a / b;
        De Otro Modo:
            Escribir -1;
    FinSegun
FinProceso
